    css: `.Input-field {
    position: relative;
    width: 250px;
}
.Input {
    width: 100%;
    height: 50px;
    padding: 14px 14px 5px;
    box-sizing: border-box;
    border: 1px solid #d4d4d8;
    border-radius: 10px;
    outline: none;
    font-size: 14px;
    background: #ffffff;
}
.Input-field label {
    position: absolute;
    left: 13px;
    top: 16px;
    color: #71717a;
    font-size: 13px;
    pointer-events: none;
    transition: .2s ease;
    background: #ffffff;
    padding: 0 4px;
}
.Input:focus {
    border-color: #6366f1;
}
.Input:focus + label,
.Input:not(:placeholder-shown) + label {
    top: -7px;
    color: #6366f1;
    font-size: 11px;
}`
