        css: `.Form {
    --input-focus: #2d8cf0;
    --font-color: #323232;
    --font-color-sub: #666;
    --bg-color: #fff;
    --main-color: #323232;
    display: flex;
    align-items: flex-end;
    justify-content: center;
    transform: scale(0.75);
    height: 320px;
}
.Form__switch {
    transform: translateY(-200px);
    position: relative;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    gap: 30px;
    width: 50px;
    height: 20px;
}
.Form__card-side::before {
    position: absolute;
    content: 'Log in';
    left: -70px;
    top: 0;
    width: 100px;
    text-decoration: underline;
    color: var(--font-color);
    font-weight: 600;
}
.Form__card-side::after {
    position: absolute;
    content: 'Sign up';
    left: 70px;
    top: 0;
    width: 100px;
    text-decoration: none;
    color: var(--font-color);
    font-weight: 600;
}
.Form__toggle {
    opacity: 0;
    width: 0;
    height: 0;
}
.Form__slider {
    box-sizing: border-box;
    border-radius: 5px;
    border: 2px solid var(--main-color);
    box-shadow: 4px 4px var(--main-color);
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background-color: var(--bg-color);
    transition: 0.3s;
}
.Form__slider::before {
    box-sizing: border-box;
    position: absolute;
    content: "";
    height: 20px;
    width: 20px;
    border: 2px solid var(--main-color);
    border-radius: 5px;
    left: -2px;
    bottom: 2px;
    background-color: var(--bg-color);
    box-shadow: 0 3px 0 var(--main-color);
    transition: 0.3s;
}
.Form__toggle:checked+.Form__slider {
    background-color: var(--input-focus);
}
.Form__toggle:checked+.Form__slider::before {
    transform: translateX(30px);
}
.Form__toggle:checked~.Form__card-side::before {
    text-decoration: none;
}
.Form__toggle:checked~.Form__card-side::after {
    text-decoration: underline;
}
.Form__inner {
    width: 300px;
    height: 350px;
    position: relative;
    background-color: transparent;
    perspective: 1000px;
    text-align: center;
    transition: transform 0.8s;
    transform-style: preserve-3d;
}
.Form__toggle:checked~.Form__inner {
    transform: rotateY(180deg);
}
.Form__front,
.Form__back {
    padding: 20px;
    position: absolute;
    width: 100%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    -webkit-backface-visibility: hidden;
    backface-visibility: hidden;
    background: lightgrey;
    gap: 20px;
    border-radius: 5px;
    border: 2px solid var(--main-color);
    box-shadow: 4px 4px var(--main-color);
    box-sizing: border-box;
}
.Form__back {
    transform: rotateY(180deg);
}
.Form__form {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 14px;
}
.Form__title {
    font-size: 22px;
    font-weight: 900;
    text-align: center;
    color: var(--main-color);
}
.Form__input {
    width: 100%;
    height: 38px;
    border-radius: 5px;
    border: 2px solid var(--main-color);
    background-color: var(--bg-color);
    box-shadow: 4px 4px var(--main-color);
    font-size: 14px;
    font-weight: 600;
    color: var(--font-color);
    padding: 5px 10px;
    outline: none;
    box-sizing: border-box;
}
.Form__input::placeholder {
    color: var(--font-color-sub);
    opacity: 0.8;
}
.Form__input:focus {
    border: 2px solid var(--input-focus);
}
.Form__btn {
    width: 120px;
    height: 38px;
    border-radius: 5px;
    border: 2px solid var(--main-color);
    background-color: var(--bg-color);
    box-shadow: 4px 4px var(--main-color);
    font-size: 15px;
    font-weight: 600;
    color: var(--font-color);
    cursor: pointer;
    transition: 0.1s;
}
.Form__btn:active {
    box-shadow: 0px 0px var(--main-color);
    transform: translate(3px, 3px);
}`
