        css: `.Form {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 280px;
    background-color: #fff;
    padding: 20px;
    border-radius: 10px;
    box-sizing: border-box;
}
.Form__flex {
    display: flex;
    width: 100%;
    gap: 6px;
}
.Form__label {
    position: relative;
    display: block;
    width: 100%;
}
.Form__input {
    width: 100%;
    padding: 10px 10px 20px 10px;
    outline: 0;
    border: 1px solid rgba(105, 105, 105, 0.397);
    border-radius: 5px;
    font-family: inherit;
    font-size: 13px;
    box-sizing: border-box;
}
.Form__label .Form__input+span {
    position: absolute;
    left: 10px;
    top: 15px;
    color: grey;
    font-size: 0.85em;
    cursor: text;
    transition: 0.3s ease;
    pointer-events: none;
}
.Form__label .Form__input:placeholder-shown+span {
    top: 15px;
    font-size: 0.85em;
}
.Form__label .Form__input:focus+span,
.Form__label .Form__input:valid+span {
    top: 28px;
    font-size: 0.65em;
    font-weight: 600;
}
.Form__label .Form__input:valid+span {
    color: green;
}
.Form__textarea {
    width: 100%;
    padding: 10px 10px 20px 10px;
    outline: 0;
    border: 1px solid rgba(105, 105, 105, 0.397);
    border-radius: 5px;
    font-family: inherit;
    font-size: 13px;
    box-sizing: border-box;
    resize: none;
}
.Form__label .Form__textarea+span {
    position: absolute;
    left: 10px;
    top: 12px;
    color: grey;
    font-size: 0.85em;
    cursor: text;
    transition: 0.3s ease;
    pointer-events: none;
}
.Form__label .Form__textarea:focus+span,
.Form__label .Form__textarea:valid+span {
    top: 46px;
    font-size: 0.65em;
    font-weight: 600;
}
.Form__label .Form__textarea:valid+span {
    color: green;
}
.Form__fancy {
    background-color: transparent;
    border: 2px solid #cacaca;
    border-radius: 0;
    box-sizing: border-box;
    cursor: pointer;
    display: inline-block;
    font-weight: 390;
    letter-spacing: 2px;
    margin: 0;
    outline: none;
    overflow: visible;
    padding: 8px 30px;
    position: relative;
    text-align: center;
    transition: all 0.3s ease-in-out;
    font-size: 13px;
    background: #fff;
}
.Form__fancy::before {
    content: " ";
    width: 1.7rem;
    height: 2px;
    background: #cacaca;
    top: 50%;
    left: 1.5em;
    position: absolute;
    transform: translateX(230%);
    transition: background 0.3s linear, width 0.3s linear;
}
.Form__text {
    font-size: 1em;
    line-height: 1.33em;
    padding-left: 2em;
    display: block;
    text-align: left;
    transition: all 0.3s ease-in-out;
    text-transform: lowercase;
    color: #818181;
    transform: translateX(30%);
}
.Form__top-key {
    height: 2px;
    width: 1.5625rem;
    top: -2px;
    left: 0.625rem;
    position: absolute;
    background: white;
    transition: width 0.5s ease-out, left 0.3s ease-out;
}
.Form__bottom-key-1 {
    height: 2px;
    width: 1.5625rem;
    right: 1.875rem;
    bottom: -2px;
    position: absolute;
    background: white;
    transition: width 0.5s ease-out, right 0.3s ease-out;
}
.Form__bottom-key-2 {
    height: 2px;
    width: 0.625rem;
    right: 0.625rem;
    bottom: -2px;
    position: absolute;
    background: white;
    transition: width 0.5s ease-out, right 0.3s ease-out;
}
.Form__fancy:hover {
    background: #cacaca;
}
.Form__fancy:hover::before {
    width: 1.5rem;
    background: white;
}
.Form__fancy:hover .Form__text {
    color: white;
    padding-left: 1.5em;
}
.Form__fancy:hover .Form__top-key {
    left: -2px;
    width: 0;
}
.Form__fancy:hover .Form__bottom-key-1,
.Form__fancy:hover .Form__bottom-key-2 {
    right: 0;
    width: 0;
}`
